    while b:
        a, b = b, a % b
    return a == 1

def median_lower(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return s[n // 2 - 1]

def smallest_multiple_up_to(n):
    def g(a, b):
        while b:
            a, b = b, a % b
        return a
    result = 1
    for i in range(2, n + 1):
        result = result * i // g(result, i)
    return result

def top_k_and_rest_sorted(nums, k):
    s = sorted(nums)
    n = len(s)
    top = list(reversed(s[n - k:])) if k > 0 else []
    rest = s[:n - k]
    return (top, rest)

def is_valid_stack_sequence(pushed, popped):
    if len(pushed) != len(popped):
        return False
    stack = []
    j = 0
    for x in pushed:
        stack.append(x)
        while stack and j < len(popped) and stack[-1] == popped[j]:
            stack.pop()
            j += 1
    return not stack

def digital_root_base(n, b):
    while n >= b:
        s = 0
        x = n
        while x > 0:
            s += x % b
            x //= b
        n = s
    return n

