def wrap_bullet(text, width, bullet):
    prefix = bullet + " "
    words = text.split()
    lines = []
    cur = ""
    limit = width - len(prefix)
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    indent = " " * len(prefix)
    out = []
    for i, line in enumerate(lines):
        out.append((prefix if i == 0 else indent) + line)
    return out

def longest_consecutive_alphabetical_run(s):
    if not s:
        return ""
    best = ""
    cur = s[0]
    for i in range(1, len(s)):
        prev_ch, ch = s[i-1], s[i]
        if prev_ch.isalpha() and ch.isalpha() and ord(ch.lower()) - ord(prev_ch.lower()) == 1:
            cur += ch
        else:
            cur = ch
        if len(cur) > len(best):
            best = cur
    return best

def balance_index(lst):
    total = sum(lst)
    left = 0
    for i, x in enumerate(lst):
        right = total - left - x
        if left == right:
            return i
        left += x
    return -1

