def is_near_palindrome(s):
    def is_pal(sub):
        return sub == sub[::-1]
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return is_pal(s[i + 1:j + 1]) or is_pal(s[i:j])
        i += 1
        j -= 1
    return True

def format_id_grouped(n, width, group):
    padded = str(n).zfill(width)
    chunks = [padded[i:i + group] for i in range(0, len(padded), group)]
    return "-".join(chunks)

def smallest_repeating_unit(s):
    n = len(s)
    if n == 0:
        return ""
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return unit
    return s

def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    chars = list(s)
    l, r = 0, len(chars) - 1
    while l < r:
        if chars[l] not in vowels:
            l += 1
        elif chars[r] not in vowels:
            r -= 1
        else:
            chars[l], chars[r] = chars[r], chars[l]
            l += 1
            r -= 1
    return ''.join(chars)

def remove_duplicate_letters_keep_first(s):
    seen = set()
    out = []
    for ch in s:
        if ch not in seen:
            seen.add(ch)
            out.append(ch)
    return ''.join(out)

def shortest_distinguishing_prefix_length(a, b):
    i = 0
    while i < len(a) and i < len(b) and a[i] == b[i]:
        i += 1
    if i == len(a):
        return len(a)
    return i + 1
